import sys

def main():
    import sys
    import math
    from collections import deque

    def is_integer_distance(p1, p2):
        dx = p1[0] - p2[0]
        dy = p1[1] - p2[1]
        dist_squared = dx * dx + dy * dy
        return int(math.isqrt(dist_squared)) ** 2 == dist_squared

    def bfs(start, graph, visited):
        queue = deque([start])
        visited[start] = True
        component = []

        while queue:
            node = queue.popleft()
            component.append(node)
            for neighbor in graph[node]:
                if not visited[neighbor]:
                    visited[neighbor] = True
                    queue.append(neighbor)

        return component

    input = sys.stdin.read().strip().split()
    n = int(input[0])
    m = int(input[1])

    points = [(x, y) for x in range(n + 1) for y in range(m + 1) if x + y > 0]
    num_points = len(points)

    graph = {i: [] for i in range(num_points)}

    for i in range(num_points):
        for j in range(i + 1, num_points):
            if not is_integer_distance(points[i], points[j]):
                graph[i].append(j)
                graph[j].append(i)

    visited = [False] * num_points
    max_component = []

    for i in range(num_points):
        if not visited[i]:
            component = bfs(i, graph, visited)
            if len(component) > len(max_component):
                max_component = component

    print(len(max_component))
    for index in max_component:
        print(points[index][0], points[index][1])

main()
